import itertools, random
MOD=998244353

def solve(A,M):
 N=len(A); indeg=[0]*N
 for p in A:indeg[p]+=1
 from collections import deque
 q=deque(i for i,x in enumerate(indeg) if x==0); order=[]
 while q:
  v=q.popleft();order.append(v);p=A[v];indeg[p]-=1
  if not indeg[p]:q.append(p)
 cyc=[x>0 for x in indeg];acc=[None]*N
 for v in order:
  f=acc[v] or [1]*M;p=A[v];pf=acc[p]
  if pf is None:pf=[1]*M;acc[p]=pf
  s=0
  for k in range(M):s=(s+f[k])%MOD;pf[k]=pf[k]*s%MOD
 seen=[0]*N;ans=1
 for v in range(N):
  if cyc[v] and not seen[v]:
   u=v; C=[]
   while not seen[u]:seen[u]=1;C.append(u);u=A[u]
   f=[1]*M
   for u in C:
    if acc[u]: f=[x*y%MOD for x,y in zip(f,acc[u])]
   ans=ans*sum(f)%MOD
 return ans
for n in range(1,7):
 for A in itertools.product(range(n),repeat=n):
  for m in range(1,4):
   b=sum(all(x[i]<=x[A[i]] for i in range(n)) for x in itertools.product(range(1,m+1),repeat=n))
   if solve(A,m)!=b: print('FAIL',A,m,solve(A,m),b);raise SystemExit
 print(n,'ok')

