import sys

def solve():
 data=list(map(int,sys.stdin.buffer.read().split()))
 n=data[0]; aa=data[1:]
 fac=[]
 for x in aa:
  fs={}; d=2
  while d*d<=x:
   while x%d==0: fs[d]=fs.get(d,0)+1; x//=d
   d+=1
  if x>1: fs[x]=fs.get(x,0)+1
  fac.append(fs)
 primes=set().union(*(f.keys() for f in fac)) if fac else set()
 ans=1
 for p in primes:
  steps=[f.get(p,0) for f in fac]
  T=sum(steps)
  powp=[1]*(T+1)
  for h in range(1,T+1): powp[h]=powp[h-1]*p%MOD
  # untouched and touched; initial heights 1..T; zero touched
  u=[0]*(T+1); z=[0]*(T+1)
  z[0]=1
  for h in range(1,T+1): u[h]=powp[h]
  for b in steps:
   nu=[0]*(T+1); nz=[0]*(T+1)
   for h in range(T+1):
    val=u[h]
    if val:
     for nh in ((h+b,) if b==0 else (h-b,h+b)):
      if 0<=nh<=T:
       w=val*powp[nh]%MOD
       if nh==0: nz[0]=(nz[0]+w)%MOD
       else: nu[nh]=(nu[nh]+w)%MOD
    val=z[h]
    if val:
     for nh in ((h+b,) if b==0 else (h-b,h+b)):
      if 0<=nh<=T:
       nz[nh]=(nz[nh]+val*powp[nh])%MOD
   u,z=nu,nz
  ans=ans*sum(z)%MOD
 print(ans)

if __name__=='__main__': solve()

