import sys

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    n=data[0]
    vals=data[1:]
    limit=max(vals)
    spf=list(range(limit+1))
    for p in range(2,int(limit**0.5)+1):
        if spf[p]==p:
            for x in range(p*p,limit+1,p):
                if spf[x]==x: spf[x]=p
    nim=0
    for x in vals:
        count=0
        while x>1:
            p=spf[x]
            x//=p
            count+=1
        nim ^= count
    print('Anna' if nim else 'Bruno')

if __name__=='__main__': main()

