from typing import List
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        events=[[] for _ in range(n+1)]
        for i,(x,y) in enumerate(conflictingPairs):
            a,b=sorted((x,y))
            events[b].append((a,i))
        first=second=0
        owner=-1
        gain=[0]*len(conflictingPairs)
        total=0
        for r in range(1,n+1):
            for a,i in events[r]:
                if a>first:
                    second=first
                    first=a
                    owner=i
                elif a==first:
                    second=first
                elif a>second:
                    second=a
            total+=r-first
            if owner!=-1 and first>second:
                gain[owner]+=first-second
        return total+max(gain)

