class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        # S(i,k) counts partitions of i performers into k nonempty unlabeled bands.
        lim = min(n, x)
        dp = [0] * (lim + 1)
        dp[0] = 1
        for i in range(1, n + 1):
            for k in range(min(i, lim), 0, -1):
                dp[k] = (dp[k - 1] + k * dp[k]) % MOD
            dp[0] = 0
        ans = 0
        falling = 1
        yp = 1
        for k in range(1, lim + 1):
            falling = falling * (x - k + 1) % MOD
            yp = yp * y % MOD
            ans = (ans + dp[k] * falling % MOD * yp) % MOD
        return ans

if __name__ == '__main__':
    for args in [(1,2,3),(5,2,1),(3,3,4)]:
        print(Solution().numberOfWays(*args))

