class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        mod = 10**9 + 7
        n = len(s)
        # Pascal triangle of binomial coefficients modulo mod.
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for i in range(1, n + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % mod

        good = [False] * (n + 1)
        for ones in range(1, n + 1):
            value = ones
            steps = 0
            while value > 1:
                value = value.bit_count()
                steps += 1
            good[ones] = 1 + steps <= k

        ans = 0
        prefix_ones = 0
        for i, bit in enumerate(s):
            remaining = n - i - 1
            if bit == '1':
                for ones in range(1, n + 1):
                    if good[ones]:
                        need = ones - prefix_ones
                        if 0 <= need <= remaining:
                            ans += comb[remaining][need]
                prefix_ones += 1
        return ans % mod

