import sys
from collections import deque

def solve():
    input = sys.stdin.readline
    n = int(input())
    g = [input().strip() for _ in range(n)]
    incoming = [[[] for _ in range(26)] for _ in range(n)]
    outmask = [[0] * 26 for _ in range(n)]
    for a in range(n):
        for b, ch in enumerate(g[a]):
            if ch != '-':
                c = ord(ch) - 97
                incoming[b][c].append(a)
                outmask[a][c] |= 1 << b
    dist = [[-1] * n for _ in range(n)]
    unseen = [(1 << n) - 1 for _ in range(n)]
    q = deque()
    for i in range(n):
        dist[i][i] = 0
        unseen[i] &= ~(1 << i)
        q.append((i, i))
    for i in range(n):
        for j, ch in enumerate(g[i]):
            if ch != '-' and dist[i][j] == -1:
                dist[i][j] = 1
                unseen[i] &= ~(1 << j)
                q.append((i, j))
    while q:
        u, v = q.popleft()
        nd = dist[u][v] + 2
        for c in range(26):
            om = outmask[v][c]
            if not om:
                continue
            for a in incoming[u][c]:
                bits = om & unseen[a]
                while bits:
                    bit = bits & -bits
                    bits -= bit
                    b = bit.bit_length() - 1
                    unseen[a] ^= bit
                    dist[a][b] = nd
                    q.append((a, b))
    print('\n'.join(' '.join(map(str, row)) for row in dist))

if __name__ == '__main__':
    solve()

