import sys, heapq

def solve():
    data=list(map(int,sys.stdin.buffer.read().split()))
    H,W,X=data[:3]
    P,Q=data[3]-1,data[4]-1
    vals=data[5:]
    seen=bytearray(H*W)
    start=P*W+Q
    seen[start]=1
    strength=vals[start]
    heap=[]
    def add(r,c):
        idx=r*W+c
        if not seen[idx]:
            seen[idx]=1
            heapq.heappush(heap,(vals[idx],idx))
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
        r,c=P+dr,Q+dc
        if 0<=r<H and 0<=c<W: add(r,c)
    while heap:
        s,idx=heap[0]
        if s*X>=strength: break
        heapq.heappop(heap)
        strength+=s
        r,c=divmod(idx,W)
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<H and 0<=nc<W: add(nr,nc)
    print(strength)

if __name__=='__main__': solve()

