def alg(a,b,m):
 n=len(a); base=[(b[0]-a[0])%m]
 for i in range(n-1):
  g=a[i+1]-a[i]; k=g//m; lo=k*m;r=(b[i+1]-b[i])%m
  h=lo+((r-lo-1)%m)+1
  if not lo<h<(k+1)*m:return -1
  base.append(base[-1]+h-g)
 s=sorted(base); med=s[n//2]; t=(-med)//m
 return min(sum(abs(x+z*m) for x in base) for z in (t,t+1))
