import sys

def main():
    a=list(map(int,sys.stdin.buffer.read().split()))
    if not a:return
    n,m=a[:2]; rows=[0]*n; j=2
    for _ in range(m):
        u,v=a[j]-1,a[j+1]-1;j+=2
        rows[u]|=1<<v;rows[v]|=1<<u
    piv=[];r=0
    for c in range(n):
        f=next((i for i in range(r,n) if rows[i]>>c&1),None)
        if f is None:continue
        rows[r],rows[f]=rows[f],rows[r]
        for i in range(n):
            if i!=r and rows[i]>>c&1:rows[i]^=rows[r]
        piv.append(c);r+=1
    ps=set(piv);basis=[]
    for f in range(n):
        if f not in ps:
            v=1<<f
            for i,c in enumerate(piv):
                if rows[i]>>f&1:v|=1<<c
            basis.append(v)
    cover=0
    for v in basis:cover|=v
    if cover!=(1<<n)-1:print('No');return
    shift=2 if m>0 and len(basis)<=58 else 0
    ans=[0]*n
    for k,v in enumerate(basis):
        for i in range(n):
            if v>>i&1:ans[i]|=1<<(k+shift)
    print('Yes');print(*ans)
