    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n,m=len(grid),len(grid[0]); N=n*m
        dirs=[(1,1),(1,-1),(-1,-1),(-1,1)]
        straight=[[array('H',[0])*N for _ in range(2)] for _ in range(4)]
        for d,(dr,dc) in enumerate(dirs):
            rows=range(n-1,-1,-1) if dr==1 else range(n)
            cols=range(m-1,-1,-1) if dc==1 else range(m)
            for r in rows:
                for c in cols:
                    i=r*m+c
                    for p,val in enumerate((2,0)):
                        if grid[r][c]==val:
                            nr,nc=r+dr,c+dc
                            straight[d][p][i]=1+(straight[d][1-p][nr*m+nc] if 0<=nr<n and 0<=nc<m else 0)
        ans=0
        for d,(dr,dc) in enumerate(dirs):
            cw=(d+1)%4; tr,tc=dirs[cw]
            rows=range(n-1,-1,-1) if dr==1 else range(n)
            cols=range(m-1,-1,-1) if dc==1 else range(m)
            h0=array('H',[0])*N; h1=array('H',[0])*N
            for r in rows:
                for c in cols:
                    i=r*m+c
                    nr,nc=r+dr,c+dc
                    if grid[r][c]==2:
                        a=b=0
                        if 0<=nr<n and 0<=nc<m: a=h1[nr*m+nc]
                        xr,xc=r+tr,c+tc
                        if 0<=xr<n and 0<=xc<m: b=straight[cw][1][xr*m+xc]
                        h0[i]=1+max(a,b)
                    elif grid[r][c]==0:
                        a=b=0
                        if 0<=nr<n and 0<=nc<m: a=h0[nr*m+nc]
                        xr,xc=r+tr,c+tc
                        if 0<=xr<n and 0<=xc<m: b=straight[cw][0][xr*m+xc]
                        h1[i]=1+max(a,b)
            for r in range(n):
                for c in range(m):
                    if grid[r][c]==1:
                        nr,nc=r+dr,c+dc
                        ans=max(ans,1+(h0[nr*m+nc] if 0<=nr<n and 0<=nc<m else 0))
        return ans

