from typing import List
class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = list(range(1, n + 1, 2))
        evens = list(range(2, n + 1, 2))
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i
        ans = []
        prev = None
        for pos in range(n):
            chosen = False
            for x in sorted(odds + evens):
                if (x % 2 == 1 and not odds) or (x % 2 == 0 and not evens):
                    continue
                if prev is not None and (x % 2) == prev:
                    continue
                rem_o = len(odds) - (x % 2 == 1)
                rem_e = len(evens) - (x % 2 == 0)
                rem_len = n - pos - 1
                # Next position must have parity opposite to x; count parity slots.
                first_parity = 1 - (x % 2)
                need_o = (rem_len + (1 if first_parity == 1 else 0)) // 2
                need_e = rem_len - need_o
                ways = fact[rem_o] * fact[rem_e] if rem_o == need_o and rem_e == need_e else 0
                if k > ways:
                    k -= ways
                else:
                    ans.append(x)
                    if x % 2: odds.remove(x)
                    else: evens.remove(x)
                    prev = x % 2
                    chosen = True
                    break
            if not chosen:
                return []
        return ans

