class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        coeff = [ (pow(10, n - 1 - i, k) + pow(10, i, k)) % k for i in range(m) ]
        if n % 2:
            coeff[-1] = pow(10, m - 1, k) % k
        dp = [0] * (m + 1)
        dp[m] = 1
        for i in range(m - 1, -1, -1):
            mask = 0
            for r in range(k):
                if (dp[i + 1] >> r) & 1:
                    for d in range(10):
                        mask |= 1 << ((r + d * coeff[i]) % k)
            dp[i] = mask
        rem = 0
        digits = []
        for i in range(m):
            lo = 1 if i == 0 else 0
            for d in range(9, lo - 1, -1):
                need = (-rem - d * coeff[i]) % k
                if (dp[i + 1] >> need) & 1:
                    digits.append(str(d))
                    rem = (rem + d * coeff[i]) % k
                    break
        left = ''.join(digits)
        return left + (left[:-1][::-1] if n % 2 else left[::-1])

