class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        nxt = [n] * n
        st = []
        for i in range(n - 1, -1, -1):
            while st and nums[st[-1]] <= nums[i]:
                st.pop()
            nxt[i] = st[-1] if st else n
            st.append(i)
        levels = n.bit_length()
        jump = [nxt]
        agg = [[nums[i] * (nxt[i] - i) for i in range(n)]]
        for _ in range(1, levels):
            prev = jump[-1]
            prevagg = agg[-1]
            nj = [n] * n
            na = [0] * n
            for i in range(n):
                mid = prev[i]
                if mid < n:
                    nj[i] = prev[mid]
                    na[i] = prevagg[i] + prevagg[mid]
                else:
                    na[i] = prevagg[i]
            jump.append(nj)
            agg.append(na)
        pref = [0] * (n + 1)
        for i, x in enumerate(nums):
            pref[i + 1] = pref[i] + x
        def cost(l, r):
            pos = l
            total = 0
            for b in range(levels - 1, -1, -1):
                q = jump[b][pos]
                if q <= r:
                    total += agg[b][pos]
                    pos = q
            total += nums[pos] * (r - pos + 1)
            return total - (pref[r + 1] - pref[l])
        ans = 0
        left = 0
        for right in range(n):
            while left <= right and cost(left, right) > k:
                left += 1
            ans += right - left + 1
        return ans

