class Solution:
    def makeStringGood(self, s: str) -> int:
        f = [0] * 26
        for c in s:
            f[ord(c) - 97] += 1
        ans = len(s)
        for k in range(1, max(f) + 1):
            dp = [f[0], abs(f[0] - k)]
            prev_delta = [f[0], f[0] - k]
            for i in range(1, 26):
                ndp = [0, 0]
                for choice in range(2):
                    d = f[i] - (k if choice else 0)
                    base = abs(d)
                    best = 10**9
                    for p in range(2):
                        benefit = min(prev_delta[p], -d) if prev_delta[p] > 0 and d < 0 else 0
                        best = min(best, dp[p] + base - benefit)
                    ndp[choice] = best
                dp = ndp
                prev_delta = [f[i], f[i] - k]
            ans = min(ans, *dp)
        return ans

