from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        first = p.find('*')
        second = p.find('*', first + 1)
        parts = (p[:first], p[first + 1:second], p[second + 1:])
        n = len(s)

        def occurrences(t):
            m = len(t)
            if m == 0:
                return list(range(n + 1))
            # KMP prefix function
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j
            out = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    out.append(i - m + 1)
                    j = pi[j - 1]
            return out

        occ = [occurrences(t) for t in parts]
        a_pos, b_pos, c_pos = occ
        if not a_pos or not b_pos or not c_pos:
            return -1
        la, lb, lc = map(len, parts)
        ans = n + 1
        for a in a_pos:
            bi = bisect_left(b_pos, a + la)
            if bi == len(b_pos):
                continue
            b = b_pos[bi]
            ci = bisect_left(c_pos, b + lb)
            if ci == len(c_pos):
                continue
            c = c_pos[ci]
            ans = min(ans, c + lc - a)
        return -1 if ans == n + 1 else ans

