import sys
from collections import deque

def solve(n,a,b):
    s=0;t=0
    for i,c in enumerate(a):
        if c=='1': s|=1<<i
    for i,c in enumerate(b):
        if c=='1': t|=1<<i
    if s==t:return 0
    q=deque([s]); d={s:0}
    while q:
        x=q.popleft(); nd=d[x]+1
        for i in range(n):
            z=0
            y=x
            while y:
                bit=y&-y;y-=bit
                p=bit.bit_length()-1
                np=p+(1 if p<i else -1 if p>i else 0)
                z|=1<<np
            if z==t:return nd
            if z not in d:
                d[z]=nd;q.append(z)
    return -1

