from typing import List
class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n=len(parent)
        children=[[] for _ in range(n)]
        for v in range(1,n): children[parent[v]].append(v)
        starts=[0]*n; ends=[0]*n
        order=[]
        stack=[(0,0)]
        while stack:
            x, exiting=stack.pop()
            if not exiting:
                starts[x]=len(order)
                stack.append((x,1))
                for y in reversed(children[x]): stack.append((y,0))
            else:
                order.append(s[x]); ends[x]=len(order)-1
        m=n
        d1=[0]*m; l=0; r=-1
        for i in range(m):
            k=1 if i>r else min(d1[l+r-i],r-i+1)
            while i-k>=0 and i+k<m and order[i-k]==order[i+k]: k+=1
            d1[i]=k
            if i+k-1>r: l=i-k+1; r=i+k-1
        d2=[0]*m; l=0; r=-1
        for i in range(m):
            k=0 if i>r else min(d2[l+r-i+1],r-i+1)
            while i-k-1>=0 and i+k<m and order[i-k-1]==order[i+k]: k+=1
            d2[i]=k
            if i+k-1>r: l=i-k; r=i+k-1
        ans=[]
        for x in range(n):
            a,b=starts[x],ends[x]
            length=b-a+1
            if length%2: ans.append(d1[(a+b)//2]>=length//2+1)
            else: ans.append(d2[(a+b+1)//2]>=length//2)
        return ans

