    n, m = data[0], data[1]
    forbidden = set()
    moves = ((2,1),(1,2),(-1,2),(-2,1),(-2,-1),(-1,-2),(1,-2),(2,-1))
    p = 2
    for _ in range(m):
        a, b = data[p], data[p+1]
        p += 2
        forbidden.add((a,b))
        for da, db in moves:
            x, y = a + da, b + db
            if 1 <= x <= n and 1 <= y <= n:
                forbidden.add((x,y))
    print(n*n - len(forbidden))

if __name__ == '__main__':
